#!/usr/bin/env bash
# Question 4: Control plane after maintenance. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q4_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF

case "${Q4_FAULT}" in
  apiserver-etcd-port)
    kubectl -n "${Q4_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q4_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^([[:space:]]*- --etcd-servers=https://127.0.0.1):2379$#\1:2380#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --etcd-servers=https://127.0.0.1:2380$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-etcd-certfile)
    kubectl -n "${Q4_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q4_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^([[:space:]]*- --etcd-certfile=)/etc/kubernetes/pki/apiserver-etcd-client.crt$#\1/etc/kubernetes/pki/etcd/apiserver-etcd-client.crt#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --etcd-certfile=/etc/kubernetes/pki/etcd/apiserver-etcd-client.crt$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  etcd-cert-path)
    kubectl -n "${Q4_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q4_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^([[:space:]]*- --cert-file=/etc/kubernetes/pki/etcd/server)\.crt$#\1.cert#' /etc/kubernetes/manifests/etcd.yaml
    grep -qE -- '- --cert-file=/etc/kubernetes/pki/etcd/server.cert$' /etc/kubernetes/manifests/etcd.yaml || { echo "could not modify /etc/kubernetes/manifests/etcd.yaml" >&2; exit 1; }
    ;;
  scheduler-command)
    sed -i -E 's#^([[:space:]]*)- kube-scheduler$#\1- kube-schedular#' /etc/kubernetes/manifests/kube-scheduler.yaml
    grep -qE -- '- kube-schedular$' /etc/kubernetes/manifests/kube-scheduler.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-scheduler.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-scheduler-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-scheduler is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "${Q4_NS}" scale deployment/web --replicas=2
    ;;
  controller-manager-kubeconfig)
    sed -i -E 's#^([[:space:]]*- --kubeconfig=/etc/kubernetes/controller-manager)\.conf$#\1.config#' /etc/kubernetes/manifests/kube-controller-manager.yaml
    grep -qE -- '- --kubeconfig=/etc/kubernetes/controller-manager.config$' /etc/kubernetes/manifests/kube-controller-manager.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-controller-manager.yaml" >&2; exit 1; }
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] && break
      sleep 3
    done
    [[ "$(kubectl -n kube-system get pod kube-controller-manager-controlplane -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null || true)" != True ]] || { echo "kube-controller-manager is still Ready" >&2; exit 1; }
    sleep 5
    kubectl -n "${Q4_NS}" scale deployment/web --replicas=2
    ;;
  kubelet-client-cert)
    kubectl -n "${Q4_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q4_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^([[:space:]]*client-certificate: /var/lib/kubelet/pki/)kubelet-client-current.pem$#\1kubelet-client.pem#' /etc/kubernetes/kubelet.conf
    grep -qE -- 'client-certificate: /var/lib/kubelet/pki/kubelet-client.pem$' /etc/kubernetes/kubelet.conf || { echo "could not modify /etc/kubernetes/kubelet.conf" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

case "${Q4_FAULT}" in
  apiserver-etcd-port)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-etcd-certfile)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  etcd-cert-path)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  scheduler-command)
    sleep 15
    [[ "$(kubectl -n "${Q4_NS}" get deployment web -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "web is still running" >&2; exit 1; }
    ;;
  controller-manager-kubeconfig)
    sleep 15
    [[ "$(kubectl -n "${Q4_NS}" get deployment web -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "web is still running" >&2; exit 1; }
    ;;
  kubelet-client-cert)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "controlplane" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && exit 0
      sleep 2
    done
    echo "the node is still Ready" >&2
    exit 1
    ;;
esac
